20	// Géométrie du menu de catégorie, en px, dans le repère de la pilule (fixed, left 24 / top 212).
21	// Doit rester alignée sur CategoriesSidebar.module.scss (.leftSidebarContainer,
22	// .categoriesToolbar, .fusionMenuContainer).
23	const MENU_OFFSET_Y = 68; // .fusionMenuContainer : top 280
24	const MENU_W = 320;
25	const MENU_R = 16;
26	// Panneau (max-height 400) + la marge que prend le col en s'étirant avant de se rompre.
27	const MENU_STAGE_H = MENU_OFFSET_Y + 400 + 40;
28	const MENU_MORPH_MS = 700;
29	
30	// Prévisualisation : panneau du haut sur toute la hauteur disponible, panneau du bas de hauteur
31	// fixe, le tout s'arrêtant à 236px du bas de l'écran (au-dessus de la barre d'aide).
32	const PREVIEW_STRETCH_MS = 520;
33	const PREVIEW_HOLD_MS = 90; // temps mort entre l'étirement et la division : deux gestes distincts
34	const PREVIEW_DIVIDE_MS = 760;
35	const PREVIEW_MORPH_MS = PREVIEW_STRETCH_MS + PREVIEW_HOLD_MS + PREVIEW_DIVIDE_MS;
36	
37	// Cascade des icônes de la pilule (Qualité/Solidité/Vitesse/...) autour d'un morph de Modélisation,
38	// dans l'ordre d'affichage (gauche → droite) : disparition dès le clic vers Modélisation
39	// (leavingToModeling), apparition au retour d'un morph de sortie (arrivingFromModeling). Symétrique
40	// à la cascade du contenu du panneau Modélisation (cf. CONTENT_STAGGER_MS dans ModelingSidebar.tsx).
41	// Avec ~8 catégories et 30ms de décalage, la cascade dure ~370ms : largement terminée avant que la
42	// déformation ne commence (`onCovered`, ~900ms après le clic).
43	const PILL_ICON_STAGGER_MS = 0.03;
44	const PILL_ICON_FADE_MS = 0.16;
45	
46	const pillIconsContainerVariants = {
47	  visible: { transition: { staggerChildren: PILL_ICON_STAGGER_MS } },
48	  hidden: { transition: { staggerChildren: PILL_ICON_STAGGER_MS } },
49	};
50	
51	const pillIconVariants = {
52	  visible: { opacity: 1, y: 0, transition: { duration: PILL_ICON_FADE_MS, ease: [0.4, 0, 0.2, 1] } },
53	  hidden: { opacity: 0, y: -6, transition: { duration: PILL_ICON_FADE_MS, ease: [0.4, 0, 0.2, 1] } },
54	};
55	
56	const SolidityIcon = () => <BicepsFlexed size={20} />;
57	
