259	interface CategoriesSidebarProps {
260	  activeCategory: string | null;
261	  onSelectCategory: (catId: string | null) => void;
262	  /**
263	   * Vrai quand ce composant est remonté directement dans l'espace Prévisualisation — après un
264	   * morph de sortie de Modélisation joué par ModelingSidebar lui-même (cf. son prop `morph`) — au
265	   * lieu d'y entrer par la mitose normale (pilule → panneaux). Les deux panneaux réels doivent
266	   * alors être affichés tels quels dès le premier rendu, sans aucune animation ici : le morph a
267	   * déjà eu lieu visuellement, ailleurs.
268	   */
269	  initialPreviewActive?: boolean;
270	  /**
271	   * Vrai dès le CLIC vers Modélisation (cf. apex-entering-modeling dans Index.tsx), ~900ms avant
272	   * que ce composant ne soit démonté sous le rideau. Le contenu qui n'a pas sa place dans
273	   * Modélisation disparaît en fondu-glissement : les icônes de la pilule (en cascade) et le panneau
274	   * du bas de Prévisualisation — jamais la forme qui va se déformer (pilule ou panneau du haut),
275	   * reprise telle quelle par ModelingSidebar.
276	   */
277	  leavingToModeling?: boolean;
278	  /**
279	   * Vrai quand ce composant est remonté à la fin d'un morph de sortie de Modélisation (lu une seule
280	   * fois, au montage) : la pilule apparaît directement opaque (ModelingSidebar vient d'en prendre la
281	   * forme) et seules ses icônes apparaissent, en cascade.
282	   */
283	  arrivingFromModeling?: boolean;
284	  /** Contenu posé au bas du panneau du bas de Prévisualisation (ex. sélecteur de vitesse). */
285	  previewLowerContent?: React.ReactNode;
286	}
287	
288	export const CategoriesSidebar: React.FC<CategoriesSidebarProps> = ({
289	  activeCategory,
290	  onSelectCategory,
291	  initialPreviewActive = false,
292	  leavingToModeling = false,
293	  arrivingFromModeling = false,
294	  previewLowerContent,
295	}) => {
296	  const iconRefs = useRef<{ [key: string]: HTMLButtonElement | null }>({});
297	  const categoriesToolbarRef = useRef<HTMLDivElement>(null);
298	  const contentRef = useRef<HTMLDivElement>(null);
299	  const patternContentRef = useRef<HTMLDivElement>(null);
300	
301	  const [thumbHeight, setThumbHeight] = useState(40);
302	  const [thumbTop, setThumbTop] = useState(8);
303	  const [hasScroll, setHasScroll] = useState(false);
304	  const [isDragging, setIsDragging] = useState(false);
305	
306	  const [patternThumbHeight, setPatternThumbHeight] = useState(40);
307	  const [patternThumbTop, setPatternThumbTop] = useState(8);
308	  const [hasPatternScroll, setHasPatternScroll] = useState(false);
309	  const [isPatternDragging, setIsPatternDragging] = useState(false);
310	
311	  const [selectedPattern, setSelectedPattern] = useState<string>('Gyroïde');
312	  const [isPatternPopupOpen, setIsPatternPopupOpen] = useState(false);
313	  const [previewActive, setPreviewActive] = useState(initialPreviewActive);
314	  // Figé au montage, jamais réévalué : `initialPreviewActive` (la PROP) suit isPreviewActive en
315	  // direct côté Index.tsx, qui devient vrai dès le tout début de la mitose normale (avant même
316	  // qu'elle soit terminée) — si le JSX plus bas réagissait à la prop plutôt qu'à cette valeur
317	  // figée, le panneau du bas basculerait du <div> normal vers le motion.div spécial EN PLEINE
318	  // mitose (un changement de `key`, donc démontage/remontage avec `initial={{opacity:0,x:-20}}`) :
319	  // exactement le clignotement observé, à la toute fin du dévoilement du rideau.
320	  const [wasInitialPreviewActive] = useState(initialPreviewActive);
321	  // Même principe : figé au montage (Index.tsx remet la prop à `false` juste après).
322	  const [wasArrivingFromModeling] = useState(arrivingFromModeling);
323	
324	  // Morphings "verre liquide" (cf. LiquidGlassMorph). Pendant qu'une forme animée est à l'écran,
325	  // les vrais éléments restent montés mais sans fond (classe .morphing) : seul leur contenu
326	  // s'estompe, par-dessus le verre animé qui en tient lieu.
327	  //
328	  // Menu de catégorie :
329	  //  - 'dividing' : la pilule enfante le panneau détaillé (ouverture)
330	  //  - 'merging'  : le panneau remonte se refondre dans la pilule (fermeture)
331	  const [morphPhase, setMorphPhase] = useState<'dividing' | 'merging' | null>(null);
332	  const menuContainerRef = useRef<HTMLDivElement>(null);
333	
334	  // Espace Prévisualisation : à l'entrée, la pilule s'étire en panneau du haut, PUIS ce panneau
335	  // enfante celui du bas (deux temps successifs d'une même timeline, cf. previewPathAt) ; les deux
336	  // panneaux restent affichés tant qu'on reste dans l'espace. À la sortie, la même timeline est
337	  // rejouée à l'envers (reverse) : les deux panneaux se refondent en pilule.
338	  //  - 'forward' : pilule → panneau haut → panneau bas (ouverture)
339	  //  - 'reverse' : panneau bas → panneau haut → pilule (fermeture)
340	  const [previewMorphPhase, setPreviewMorphPhase] = useState<'forward' | 'reverse' | null>(null);
341	  const [previewPanelsBorn, setPreviewPanelsBorn] = useState(initialPreviewActive);
342	  const previewActiveRef = useRef(initialPreviewActive);
343	  const onSelectCategoryRef = useRef(onSelectCategory);
344	  onSelectCategoryRef.current = onSelectCategory;
345	
346	  const startYRef = useRef(0);
347	  const startScrollTopRef = useRef(0);
348	
349	  useEffect(() => {
350	    const handlePreviewToggled = (e: CustomEvent<{ active: boolean }>) => {
351	      const active = !!e.detail?.active;
352	      if (active && !previewActiveRef.current) {
353	        // La pilule devient le panneau du haut : un menu de catégorie encore ouvert se ferme
354	        // sans animation plutôt que de se superposer à la mitose.
355	        setMorphPhase(null);
356	        onSelectCategoryRef.current(null);
357	        setPreviewPanelsBorn(false);
358	        setPreviewMorphPhase('forward');
359	      } else if (!active && previewActiveRef.current) {
360	        // Sortie de l'espace : les deux panneaux se refondent en pilule (même timeline, à
361	        // l'envers) avant de démonter — jamais de disparition instantanée. `previewActive` lui-
362	        // même ne repasse à false qu'à la fin de cette animation (cf. onDone du morph), pour que
363	        // les panneaux réels restent montés (silencieux, cf. .morphing) tout du long.
364	        setPreviewMorphPhase('reverse');
365	        return;
366	      }
367	      previewActiveRef.current = active;
368	      setPreviewActive(active);
369	    };
370	    window.addEventListener('apex-preview-toggled', handlePreviewToggled as EventListener);
371	    return () => {
372	      window.removeEventListener('apex-preview-toggled', handlePreviewToggled as EventListener);
373	    };
374	  }, []);
375	
376	  const menuPathAt = useCallback((t: number, dx: number, dy: number) => {
377	    // Hauteur réelle du panneau (plafonnée par son max-height), lue sur l'élément monté invisible.
378	    const menuH = menuContainerRef.current?.offsetHeight ?? 0;
379	    return mitosisPath(PILL, { x: 0, y: MENU_OFFSET_Y, w: MENU_W, h: menuH, r: MENU_R }, t, dx, dy);
380	  }, []);
381	
382	  const previewPathAt = useCallback((t: number, dx: number, dy: number) => {
