    <div className={styles.container} data-apex-chrome-panel>
      <AnimatePresence>
        {!previewActive && !modelingActive && (
          <motion.div
            className={styles.toolbar}
            initial={{ opacity: 0, x: -20 }}
            animate={{ opacity: 1, x: 0 }}
