              x: -20,
              transition: {
                duration: modelingActive ? ELEMENTS_FADE_MS / 1000 : 0.9,
                ease: modelingActive ? 'easeInOut' : 'linear',
              },
            }}
            transition={{
              opacity: { duration: 0.9, ease: 'linear' },
              x: { duration: 0.9, ease: 'easeInOut' },
            }}
          >
        <div className={styles.content}>
          {models.length === 0 ? (
            <motion.div 
              initial={{ opacity: 0 }} 
              animate={{ opacity: 1 }} 
              exit={{ opacity: 0 }} 
              className={styles.emptyText}
            >
              Aucun modèle sur le plateau
            </motion.div>
          ) : (
            <ul className={styles.treeList}>
              <AnimatePresence>
                {models.map((model) => {
                  const isSelected = selectedModelNames.has(model.name);
                  const isExpanded = !!expandedModels[model.name];
                  return (
                    <motion.li 
                      key={model.id} 
                      className={styles.treeNode}
                      initial={{ opacity: 0, height: 0, scale: 0.9 }}
                      animate={{ opacity: 1, height: 'auto', scale: 1 }}
                      exit={{ opacity: 0, height: 0, scale: 0.9, marginBottom: 0 }}
                      transition={{ duration: 0.25, ease: [0.16, 1, 0.3, 1] }}
