                      <div 
                        className={`${styles.nodeRow} ${isSelected ? styles.selectedNode : ''}`}
                        onClick={(e) => {
                          setSelectedModelName(model.name);
                          window.dispatchEvent(new CustomEvent('apex-select-model', {
                            detail: { name: model.name, additive: e.ctrlKey || e.metaKey }
                          }));
                        }}
