1	import React, { useEffect, useRef, useState } from 'react';
2	import styles from './ModelStatusBox.module.scss';
3	import { Box, ChevronRight } from 'lucide-react';
4	import { motion, AnimatePresence } from 'framer-motion';
5	import { ELEMENTS_FADE_MS, MODEL_TREE_TOP, MODEL_TREE_PILL_GAP, PILL_TOP } from '@/utils/spaceMorphGeometry';
6	
7	interface SubMeshItem {
8	  id: string;
9	  name: string;
10	  color: string;
11	}
12	
13	interface ModelItem {
14	  id: string;
15	  name: string;
16	  children: SubMeshItem[];
17	}
18	
19	export const ModelStatusBox: React.FC = () => {
20	  const [models, setModels] = useState<ModelItem[]>([]);
21	  const [selectedModelName, setSelectedModelName] = useState<string | null>(null);
22	  const [selectedModelNames, setSelectedModelNames] = useState<Set<string>>(new Set());
23	  const [expandedModels, setExpandedModels] = useState<Record<string, boolean>>({});
24	  const [previewActive, setPreviewActive] = useState(false);
25	  // Le mode modélisation a sa propre arborescence (les corps) : celle des modèles importés
26	  // ferait doublon, on l'escamote comme en mode Prévisualisation.
27	  const [modelingActive, setModelingActive] = useState(false);
28	  const toolbarRef = useRef<HTMLDivElement>(null);
29	
30	  useEffect(() => {
31	    const handlePreviewToggled = (e: CustomEvent<{ active: boolean }>) => {
32	      setPreviewActive(!!e.detail?.active);
33	    };
34	    const handleModeChanged = (e: CustomEvent<{ mode: 'slicer' | 'modeling' }>) => {
35	      setModelingActive(e.detail?.mode === 'modeling');
36	    };
