// plutôt que de se faire recouvrir. On mesure la hauteur réellement rendue et on ne diffuse que le
// dépassement au-delà de la hauteur de base prévue par la mise en page (MODEL_TREE_BASE_H).
useEffect(() => {
  const el = toolbarRef.current;
  if (!el || previewActive || modelingActive) {
    window.dispatchEvent(new CustomEvent('apex-model-tree-resized', { detail: { overflow: 0 } }));
    return;
  }
  const notify = () => {
    const overflow = Math.max(0, el.offsetHeight - MODEL_TREE_BASE_H);
    window.dispatchEvent(new CustomEvent('apex-model-tree-resized', { detail: { overflow } }));
  };
  const observer = new ResizeObserver(notify);
  observer.observe(el);
  notify();
  return () => {
    observer.disconnect();
    window.dispatchEvent(new CustomEvent('apex-model-tree-resized', { detail: { overflow: 0 } }));
  };
}, [previewActive, modelingActive]);

