const handleKeyDown = (e: KeyboardEvent) => {
  if (e.key === 'Delete' || e.key === 'Backspace') {
    const selection = selectedMeshesRef.current;
    if (selection.size > 0) {
      let confirmed = true;
      if (selection.size > 1) {
        confirmed = window.confirm(`Voulez-vous vraiment supprimer les ${selection.size} modèles sélectionnés ?`);
      }
      if (confirmed) {
        selection.forEach(mesh => {
          if (mesh && !mesh.isDisposed()) {
            const meshName = mesh.name;
            modelsRef.current.delete(mesh);
            mesh.dispose();
            window.dispatchEvent(new CustomEvent('apex-mesh-deleted', { detail: { name: meshName } }));
          }
        });
        selection.clear();
        setSelectedMeshName(null);
        updateHighlight();
        gizmoManager.positionGizmoEnabled = false;
        gizmoManager.rotationGizmoEnabled = false;
        gizmoManager.scaleGizmoEnabled = false;
        gizmoManager.attachToMesh(null);
        window.dispatchEvent(new CustomEvent('apex-mesh-selected', { detail: { name: null, names: [], subMeshes: [] } }));
      }
    }
    return;
  }

  // Ctrl+C / Ctrl+V (Cmd sur Mac) : copier/coller les modèles du plateau sélectionnés. Ignoré
  // si le focus est sur un champ texte (cf. Sidebar.tsx, même garde-fou) pour ne pas voler un
  // copier-coller de texte normal ailleurs dans l'interface.
  const isTextField = ['INPUT', 'TEXTAREA'].includes((e.target as HTMLElement)?.tagName);
  if (isTextField) return;
  const ctrlOrCmd = e.ctrlKey || e.metaKey;
  if (!ctrlOrCmd) return;

  const key = e.key.toLowerCase();
  if (key === 'c') {
    const selection = Array.from(selectedMeshesRef.current);
    if (selection.length === 0) return;
    clipboardMeshNamesRef.current = selection.map((m) => m.name);
  } else if (key === 'v') {
    e.preventDefault();
    pasteClipboard();
  }
};
window.addEventListener('keydown', handleKeyDown);

